INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-req-01', 'requirements', 1, 'Заказчик говорит: «Сделайте, чтобы было удобно работать с заявками». Что это?', '["Готовое требование, можно передавать в разработку","Потребность (need), которую надо раскрыть в требования через вопросы","Бизнес-процесс, который надо нарисовать в BPMN","Нефункциональное требование к юзабилити"]'::jsonb, 1, '«Удобно» — это потребность, а не требование. Задача аналитика: выяснить, кто, в каком сценарии и что именно делает, какие есть критерии «удобства» (время операции, число кликов, число ошибок), и превратить это в проверяемые требования.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-req-02', 'requirements', 1, 'Какая формулировка критерия приёмки проверяема?', '["Система должна работать быстро и стабильно","Форма регистрации должна быть удобной для пользователя","При вводе телефона в формате +7 (999) 123-45-67 система сохраняет его как 79991234567 и отображает в профиле в исходном формате","Поиск должен быть релевантным"]'::jsonb, 2, 'Проверяемый критерий описывает конкретное входное воздействие и ожидаемый результат, который можно воспроизвести и зафиксировать. «Быстро», «удобно», «релевантно» без чисел и условий — непроверяемые формулировки.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-req-03', 'requirements', 2, 'Что такое «альтернативный сценарий» в use case?', '["Сценарий, который описывает поведение другой системы","Ветвление основного потока при определённых условиях (ошибка, другой выбор, исключение)","Запасной план внедрения функциональности","Сценарий тестирования, написанный QA"]'::jsonb, 1, 'Альтернативные сценарии описывают, как развивается взаимодействие при отклонении от основного потока: ошибка валидации, отказ внешнего сервиса, отмена пользователем. Именно их отсутствие — главная причина «недоделанных» фич.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-req-04', 'requirements', 2, 'Чем пользовательское требование отличается от системного?', '["Ничем, это синонимы","Пользовательское описывает, что нужно бизнесу/пользователю (цель и правила), системное — как это реализует система (поля, интерфейсы, алгоритмы)","Пользовательское пишет аналитик, системное — разработчик","Системное требование всегда нефункциональное"]'::jsonb, 1, 'Пользовательские требования отвечают на «что и зачем» на языке бизнеса, системные — на «как именно» на языке реализации. Смешение уровней приводит к тому, что заказчик согласует детали реализации, а бизнес-правила остаются неявными.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-req-05', 'requirements', 2, 'Что из списка — нефункциональное требование?', '["Пользователь может отменить заказ до передачи в доставку","Система должна выдерживать 500 одновременных пользователей с временем отклика p95 ≤ 2 секунд","При отклонении оплаты заказ переходит в статус PAYMENT_FAILED","Отчёт по продажам формируется за прошедший месяц"]'::jsonb, 1, 'НФТ описывают свойства системы (производительность, доступность, безопасность, масштабируемость), а не конкретное поведение. Первые три варианта — функциональные требования.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-req-06', 'requirements', 3, 'Требования противоречат: «все данные доступны всем сотрудникам» и «персональные данные клиентов защищены». Что делает аналитик?', '["Выбирает то требование, которое предложил руководитель выше рангом","Фиксирует конфликт, выясняет бизнес-цели и ограничения обеих сторон, предлагает варианты (роли, объём данных, обезличивание) и передаёт решение владельцам с оценкой последствий","Реализует оба требования: даёт доступ, но шифрует данные","Откладывает противоречие до начала разработки"]'::jsonb, 1, 'Аналитик не принимает решение единолично, но обязан сделать конфликт явным, предложить варианты с последствиями и зафиксировать, кто принимает решение. Шифрование не решает конфликт: доступ «всем» противоречит политике ПДн и, скорее всего, 152-ФЗ.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-req-07', 'requirements', 3, 'Признак качественно собранного требования (по INVEST для user story)?', '["История максимально большая, чтобы охватить всю функциональность","История независима, оцениваема, мала настолько, чтобы войти в спринт, имеет ценность и проверяемые критерии","История описывает техническую реализацию: таблицы, эндпоинты, алгоритмы","История согласована с руководителем разработки"]'::jsonb, 1, 'INVEST: Independent, Negotiable, Valuable, Estimable, Small, Testable. Большие истории (эпики) декомпозируют, технические детали выносят в дизайн, ценность формулируют с точки зрения пользователя.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-int-01', 'integrations', 1, 'Какой HTTP-метод идемпотентен по спецификации?', '["POST","PUT","PATCH (без дополнительных условий)","CONNECT"]'::jsonb, 1, 'PUT идемпотентен: повторный запрос с тем же телом даёт то же состояние ресурса. POST не идемпотентен (каждый вызов может создавать новую сущность), PATCH — только если операция по сути идемпотентна, GET/DELETE/HEAD/PUT — идемпотентны по определению RFC.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-int-02', 'integrations', 1, 'Что вернёт корректный REST API при создании новой сущности?', '["200 OK с пустым телом","201 Created с заголовком Location и телом созданного ресурса","204 No Content всегда","302 Found"]'::jsonb, 1, '201 Created — стандартный ответ на успешное создание, Location указывает URI нового ресурса. 200 тоже допустим, но 201 точнее; 204 означает «успешно, тела нет» и обычно используется для DELETE.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-int-03', 'integrations', 2, 'Зачем нужен Idempotency-Key в платёжном API?', '["Для шифрования запроса","Чтобы повторная отправка того же запроса (ретрай клиента, обрыв связи) не привела к повторному выполнению операции","Для ускорения ответа сервера","Для идентификации пользователя"]'::jsonb, 1, 'Ключ идемпотентности позволяет серверу распознать повтор запроса и вернуть ранее сохранённый результат вместо выполнения операции заново. Это критично для списаний: сеть ненадёжна, клиенты ретраят.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-int-04', 'integrations', 2, 'Что такое контракт API и где он фиксируется в современной практике?', '["Устная договорённость команд","OpenAPI/Swagger-спецификация или аналог, по которой генерируют клиенты, моки и contract-тесты","Договор между юридическими лицами","README в репозитории сервиса"]'::jsonb, 1, 'Машиночитаемая спецификация (OpenAPI, AsyncAPI, Protobuf/IDL) — источник истины: по ней идут codegen, моки для параллельной разработки, contract-тесты и валидация изменений на breaking changes.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-int-05', 'integrations', 2, 'Какой код ответа означает «запрос принят, обработка ещё не завершена»?', '["200","201","202","204"]'::jsonb, 2, '202 Accepted — сервер принял запрос, но обработка не завершена (асинхронный сценарий). Клиенту обычно дают ссылку на статус или отправляют результат webhook-ом/опросом.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-int-06', 'integrations', 3, 'При интеграции через брокер сообщений (Kafka) какую гарантию доставки вы получаете «из коробки» при стандартной настройке консьюмера?', '["Exactly-once — сообщение обработается ровно один раз","At-most-once — сообщение может потеряться, но не задвоиться","At-least-once — возможны дубли, поэтому потребитель должен быть идемпотентным","Гарантий нет, всё зависит от сети"]'::jsonb, 2, 'Стандартная схема (обработали → закоммитили offset) даёт at-least-once: при сбое между обработкой и коммитом сообщение придёт снова. Отсюда требование идемпотентности потребителя. Exactly-once достижим, но требует транзакционных механизмов и всё равно не отменяет идемпотентность бизнес-эффектов.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-int-07', 'integrations', 3, 'Внешний сервис возвращает 500 примерно на 2% запросов. Ретраи с какой стратегией безопаснее всего?', '["Немедленно повторять до успеха","Повторять с фиксированной паузой 100 мс, 10 попыток","Экспоненциальный backoff с джиттером, ограниченным числом попыток, и только для идемпотентных операций или с ключом идемпотентности","Не повторять вообще, сразу показывать ошибку пользователю"]'::jsonb, 2, 'Экспоненциальная пауза с джиттером не создаёт синхронную волну ретраев («thundering herd»), лимит попыток защищает от бесконечных циклов, а идемпотентность — от двойных операций. Немедленные и частые ретраи добивают деградирующий сервис.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-int-08', 'integrations', 2, 'Чем SOAP принципиально отличается от REST?', '["SOAP всегда работает поверх HTTP, REST — только поверх TCP","SOAP — протокол со строгой схемой (WSDL), XML и встроенными стандартами (WS-Security, WS-ReliableMessaging); REST — архитектурный стиль поверх HTTP с ресурсами и методами","SOAP быстрее за счёт бинарного формата","REST не поддерживает ошибки"]'::jsonb, 1, 'SOAP — протокол с жёстким контрактом и стандартами расширения; REST — стиль архитектуры, использующий семантику HTTP. На практике SOAP-интеграции тяжелее, но дают строгую типизацию и встроенные механизмы безопасности/надёжности.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-data-01', 'data', 1, 'Какой запрос вернёт количество заказов по каждому клиенту, включая клиентов без заказов?', '["SELECT c.id, COUNT(o.id) FROM clients c JOIN orders o ON o.client_id = c.id GROUP BY c.id","SELECT c.id, COUNT(o.id) FROM clients c LEFT JOIN orders o ON o.client_id = c.id GROUP BY c.id","SELECT c.id, COUNT(*) FROM clients c, orders o WHERE o.client_id = c.id","SELECT client_id, COUNT(*) FROM orders GROUP BY client_id"]'::jsonb, 1, 'LEFT JOIN сохраняет строки клиентов без заказов (COUNT по o.id даст 0, тогда как COUNT(*) посчитал бы саму строку JOIN как 1). INNER JOIN (варианты 1 и 3) отбросит клиентов без заказов, вариант 4 не покажет их вовсе.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-data-02', 'data', 1, 'Что нарушено в таблице: заказ_id, клиент_ФИО, клиент_телефон, клиент_город, сумма? Одна строка — один заказ.', '["Первая нормальная форма","Вторая нормальная форма","Третья нормальная форма: неключевые атрибуты клиента зависят от client_id транзитивно через заказ","Ничего, это нормальная денормализация"]'::jsonb, 2, 'Данные клиента зависят не от заказа, а от клиента — это транзитивная зависимость (нарушение 3НФ). Следствия: дублирование, аномалии обновления (клиент переехал — править во всех его заказах), расхождения. Решение: вынести клиента в отдельную сущность.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-data-03', 'data', 2, 'Запрос фильтрует WHERE DATE(created_at) = CURRENT_DATE. Таблица большая, индекс по created_at есть. Что произойдёт?', '["Индекс будет использован — всё оптимально","Индекс, скорее всего, не будет использован: функция над колонкой делает предикат несаржируемым, будет Seq Scan","Запрос упадёт с ошибкой","PostgreSQL автоматически перепишет запрос"]'::jsonb, 1, 'Обёртка колонки в функцию мешает использованию обычного индекса. Правильно: диапазон created_at >= today AND created_at < tomorrow. Альтернатива — функциональный индекс по DATE(created_at), если изменить запрос нельзя.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-data-04', 'data', 2, 'Что покажет EXPLAIN ANALYZE в отличие от EXPLAIN?', '["Только текст запроса","План с фактическим временем выполнения узлов и фактическим числом строк, то есть реальное исполнение запроса","Оценку стоимости без выполнения","Список индексов таблицы"]'::jsonb, 1, 'EXPLAIN даёт план и оценки планировщика; EXPLAIN ANALYZE реально выполняет запрос и показывает фактические строки/время. Расхождение оценки и факта — главный сигнал устаревшей статистики или неверных предикатов.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-data-05', 'data', 3, 'Зачем нужен покрывающий (covering) индекс с INCLUDE?', '["Чтобы индекс занимал меньше места","Чтобы запрос мог получить все нужные колонки из индекса, не обращаясь к таблице (index-only scan)","Чтобы ускорить вставку строк","Чтобы заменить внешний ключ"]'::jsonb, 1, 'INCLUDE добавляет в индекс неключевые колонки: планировщик может выполнить index-only scan и не читать строки таблицы. Это резко ускоряет аналитические выборки, но увеличивает размер индекса и стоимость записи.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-data-06', 'data', 3, 'Чем OLAP-нагрузка отличается от OLTP и почему отчёты не выполняют на операционной БД?', '["Ничем, это одно и то же","OLTP — много коротких транзакций на запись/чтение по ключу; OLAP — редкие тяжёлые агрегирующие запросы по большим объёмам. Отчёт на OLTP-базе забирает IO/CPU и блокировки у продуктивных транзакций","OLAP всегда быстрее OLTP","OLTP не поддерживает индексы"]'::jsonb, 1, 'Разные профили нагрузки требуют разных движков и ресурсов: тяжёлый скан миллионов строк ради отчёта деградирует оформление заказов. Решение — реплика, витрина или отдельное хранилище (ClickHouse, Greenplum).', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-data-07', 'data', 2, 'Что такое EAV-модель и когда её применение оправдано?', '["Модель «сущность-атрибут-значение» для разнородных динамических свойств; оправдана, когда набор атрибутов заранее неизвестен и часто меняется","Модель шифрования данных","Способ индексации JSON","Модель хранения версий документов"]'::jsonb, 0, 'EAV даёт гибкость (атрибуты добавляются без DDL), но усложняет запросы, типизацию и производительность. Альтернативы: JSONB-колонки со схемой на уровне приложения, отдельные таблицы атрибутов по категориям.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-arch-01', 'architecture', 1, 'Что такое микросервисная архитектура простыми словами?', '["Разделение системы на небольшие независимо разворачиваемые сервисы, каждый со своей зоной ответственности и своими данными","Любая система, написанная на нескольких языках","Система, развёрнутая в контейнерах","Монолит, разрезанный на модули внутри одного процесса"]'::jsonb, 0, 'Ключевые признаки: независимое развёртывание, граница по бизнес-возможности, своя БД (database per service), взаимодействие через API/события. Контейнеры — способ упаковки, а не признак архитектуры.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-arch-02', 'architecture', 2, 'Что такое distributed transaction и почему в микросервисах вместо неё используют сагу?', '["Это одно и то же","2PC требует блокировок и синхронности всех участников и плохо переносит отказы; сага — набор локальных транзакций с компенсирующими действиями","Сага быстрее, потому что не пишет в БД","2PC не поддерживается ни одной СУБД"]'::jsonb, 1, 'Двухфазный коммит синхронен и создаёт единую точку отказа координатора. Сага жертвует атомарностью ради доступности: каждый шаг — локальная транзакция, при сбое выполняются компенсации (откат бизнес-эффекта, а не транзакции).', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-arch-03', 'architecture', 2, 'Для чего нужен паттерн Outbox?', '["Для отправки писем","Для атомарной записи бизнес-данных в БД и события в брокер: событие пишется в таблицу той же транзакцией, затем relay публикует его","Для кэширования ответов API","Для хранения исходящих HTTP-запросов"]'::jsonb, 1, 'Без outbox возможны рассинхроны: БД закоммичена — публикация не удалась (или наоборот). Outbox решает это локальной транзакцией; relay/CDC доставляет события в брокер с гарантией at-least-once.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-arch-04', 'architecture', 2, 'Что делает circuit breaker?', '["Шифрует трафик между сервисами","Прекращает вызовы к неисправному сервису на время, давая ему восстановиться, и быстро возвращает ошибку/фолбэк вместо ожидания таймаута","Ускоряет ответы за счёт кэша","Балансирует нагрузку между инстансами"]'::jsonb, 1, 'Breaker считает долю ошибок и при превышении порога переходит в open: запросы не идут к деградирующему сервису, вызывающий получает быстрый отказ или фолбэк. Через время — half-open с пробными запросами. Это предотвращает каскадные отказы.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-arch-05', 'architecture', 3, 'Как обеспечить порядок обработки событий одного заказа в Kafka при параллельном потреблении?', '["Одной партицией на весь топик","Партиционированием по ключу orderId: все события заказа попадут в одну партицию и будут читаться последовательно, а разные заказы пойдут параллельно","Сортировкой событий в потребителе по времени","Порядок в Kafka гарантировать невозможно"]'::jsonb, 1, 'Ключ партиционирования даёт порядок внутри партиции и параллельность между партициями. Одна партиция на топик убила бы пропускную способность; сортировка в потребителе не спасает от задержанных сообщений.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-arch-06', 'architecture', 3, 'Что означает CAP-теорема для проектирования распределённой системы?', '["Можно получить всё сразу: согласованность, доступность и устойчивость к разделению","При сетевом разделении (P) приходится выбирать между согласованностью (C) и доступностью (A)","Теорема касается только баз данных NoSQL","Доступность всегда важнее согласованности"]'::jsonb, 1, 'В распределённой системе partition tolerance обязателен, поэтому при разбиении сети вы жертвуете либо согласованностью (отвечаем, возможно, устаревшими данными), либо доступностью (отказываем в обслуживании). Для платежей обычно выбирают CP с компенсациями, для ленты — AP.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-arch-07', 'architecture', 1, 'Что такое антикоррупционный слой (ACL) в интеграции систем?', '["Средство защиты от вирусов","Прослойка, которая транслирует модель внешней системы в нашу модель, не давая чужим понятиям и структурам протечь в ядро","Слой шифрования данных","Модуль логирования интеграций"]'::jsonb, 1, 'ACL изолирует нас от чужой модели: смена контракта партнёра затрагивает только адаптер, а не бизнес-логику. Это же даёт возможность обратимости при миграциях (SOAP→REST).', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-mod-01', 'modeling', 1, 'Какая диаграмма показывает порядок обмена сообщениями между участниками во времени?', '["Диаграмма классов","Sequence diagram (диаграмма последовательности)","ER-диаграмма","Диаграмма компонентов"]'::jsonb, 1, 'Sequence-диаграмма отображает взаимодействия участников во времени с порядком сообщений — основной инструмент аналитика для описания интеграционных сценариев. В BPMN аналогом частично выступает пул/дорожки с потоком сообщений.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-mod-02', 'modeling', 1, 'Что показывает BPMN-элемент «шлюз по умолчанию» (default flow)?', '["Ветку, по которой поток идёт, если ни одно условие других исходящих потоков не выполнилось","Начало процесса","Сообщение внешней системе","Ошибку в процессе"]'::jsonb, 0, 'Default flow в exclusive gateway — путь «иначе». Его отсутствие — частая ошибка моделирования: процесс «зависает», когда ни одно условие не истинно.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-mod-03', 'modeling', 2, 'Чем C4 Context отличается от C4 Container?', '["Ничем, это разные названия одного уровня","Context показывает систему и её пользователей/внешние системы, Container — из каких разворачиваемых частей (приложения, БД, очереди) состоит система","Container детальнее Context в части классов и методов","Context рисуется разработчиками, Container — аналитиками"]'::jsonb, 1, 'C4: Context (система в окружении), Container (разворачиваемые единицы и технологии), Component (компоненты внутри контейнера), Code. Каждый уровень — свой масштаб и своя аудитория.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-mod-04', 'modeling', 2, 'На диаграмме состояний (state machine) что такое guard?', '["Защита диаграммы от изменений","Условие, при выполнении которого переход по событию разрешён","Начальное состояние","Действие при входе в состояние"]'::jsonb, 1, 'Guard — предикат перехода: событие произошло, но переход выполняется только если условие истинно (например, «отмена разрешена, если ресторан ещё не принял заказ»). Без guards модель допускает невозможные переходы.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-mod-05', 'modeling', 3, 'Когда аналитику стоит выбрать ER-диаграмму, а не диаграмму классов?', '["Никогда, это одно и то же","Когда обсуждаем структуру хранения данных с разработкой и ДБA; диаграмма классов — когда описываем объектную модель предметной области и поведение","ER-диаграмма нужна только для NoSQL","Диаграмма классов устарела"]'::jsonb, 1, 'ER — про данные и связи в хранилище (таблицы, ключи, cardinality). Диаграмма классов — про доменную модель с операциями и наследованием. Они дополняют друг друга, и смешение уровней — частая проблема коммуникации.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-proc-01', 'process', 1, 'Кто такой стейкхолдер проекта?', '["Только заказчик, который платит","Любая сторона, влияющая на проект или затрагиваемая его результатом","Руководитель команды разработки","Пользователь системы"]'::jsonb, 1, 'Стейкхолдеры включают заказчика, пользователей, разработку, эксплуатацию, безопасность, юристов, поддержку, регуляторов. Их карта (влияние/интерес) — рабочий инструмент аналитика.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-proc-02', 'process', 2, 'Что такое декомпозиция задачи и зачем она аналитику?', '["Удаление лишних требований из скоупа","Разбиение крупной работы на оцениваемые части, чтобы команда могла дать оценку, а бизнес — увидеть прогресс и приоритеты","Перевод требований в код","Составление графика отпусков команды"]'::jsonb, 1, 'Без декомпозиции оценка «фича займёт квартал» непроверяема. Разбиение на пользовательские истории/задачи с критериями приёмки даёт основу планирования и раннего обнаружения рисков.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-proc-03', 'process', 2, 'На встрече заказчик меняет требование, которое уже в разработке. Что делает аналитик?', '["Сразу правит задачи в трекере и сообщает разработке","Фиксирует изменение, оценивает влияние (сроки, стоимость, зависимые требования, уже сделанная работа), согласует приоритет с владельцами и только затем меняет скоуп","Отказывает заказчику: изменения после старта невозможны","Ждёт конца спринта и ничего не делает"]'::jsonb, 1, 'Управление изменениями — процесс: регистрация, оценка влияния, решение владельца приоритета, обновление артефактов. Молчаливая правка задач создаёт хаос в команде, а отказ «нельзя» противоречит agile-практике.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-proc-04', 'process', 3, 'Что такое RACI и зачем он в проекте?', '["Методика оценки рисков","Матрица ответственности: Responsible, Accountable, Consulted, Informed — кто делает, кто отвечает за результат, с кем советуемся, кого информируем","Формат требований","Инструмент автоматизации тестирования"]'::jsonb, 1, 'RACI снимает типичные проблемы: решение принимают не те, согласования затягиваются, никто не чувствует ответственности. Ключевое правило: Accountable на каждую работу — ровно один.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-proc-05', 'process', 3, 'Как аналитику понять, что требование готово к передаче в разработку (definition of ready)?', '["Требование написано красиво и без опечаток","Есть критерии: понятны цель и ценность, описаны сценарии включая альтернативные, заданы НФТ, определены данные и интеграции, известны зависимости, есть макеты/примеры, команда может оценить объём","Требование согласовано одним руководителем","Требование не старше двух недель"]'::jsonb, 1, 'DoR — проверяемый чек-лист готовности. Его отсутствие приводит к тому, что разработка додумывает детали сама, а на демо выясняется расхождение ожиданий.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-qual-01', 'quality', 1, 'Что такое feature flag (флаг функциональности)?', '["Признак ошибки в коде","Переключатель, позволяющий включить/выключить функциональность без релиза: канарейка, постепенный rollout, быстрый откат","Метка версии приложения","Флаг в системе мониторинга"]'::jsonb, 1, 'Флаги отделяют деплой от релиза: код на проде, но функция включается для части пользователей. Это основной механизм безопасной выкатки и отката.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-qual-02', 'quality', 2, 'Что из перечисленного — метрика наблюдаемости (observability)?', '["Число строк кода в сервисе","p95 времени ответа, доля ошибок, consumer lag, saturation ресурсов","Количество задач в бэклоге","Число релизов за месяц"]'::jsonb, 1, 'Наблюдаемость строится на метриках, логах и трейсах: latency (p50/p95/p99), error rate, saturation, traffic — «золотые сигналы». Без них деградацию замечают пользователи, а не вы.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-qual-03', 'quality', 2, 'Зачем аналитику участвовать в приёмке (UAT), если есть QA?', '["QA не умеет тестировать","QA проверяет соответствие требованиям и работоспособность, аналитик — что решена бизнес-задача, данные корректны, сценарии заказчика покрыты, и требования не разъехались в процессе","Чтобы подписать документ для бухгалтерии","Участие аналитика необязательно и считается плохой практикой"]'::jsonb, 1, 'Ответственности разные: тестирование на соответствие спецификации ≠ подтверждение ценности для бизнеса. Аналитик сверяет результат с целью и данными, а также фиксирует отклонения и решения.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-qual-04', 'quality', 3, 'Что означает «данные тихо разъезжаются» и как аналитик это предотвращает?', '["Это про медленную сеть — ускоряем канал","Системы дают разные цифры по одному показателю без явных ошибок; предотвращается едиными определениями метрик, сверками (reconciliation), проверками качества данных и алертами на расхождения","Это проблема только бухгалтерии","Такое бывает только при миграциях"]'::jsonb, 1, 'Классический пример: три отдела считают выручку по-разному. Лечение — словарь метрик с владельцами, слоистая модель данных, автоматические сверки и видимые строки «не распределено из-за качества данных».', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-qual-05', 'quality', 3, 'Каким должен быть план отката (rollback plan) у изменения?', '["План отката не нужен, если изменение протестировано","Заранее описанным: условия запуска отката, механика, время, кто принимает решение, что происходит с данными, и точка, после которой откат невозможен","Общим для всех изменений: «восстановить из бэкапа»","Описанным после инцидента"]'::jsonb, 1, 'Откат проектируют до изменения: с флагами, обратной синхронизацией данных и явной точкой невозврата. «Восстановить из бэкапа» на живой системе часто означает потерю данных пользователей.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-qual-06', 'quality', 2, 'Что такое SLA и чем он отличается от SLO?', '["Это одно и то же","SLA — соглашение с внешним потребителем (включая последствия нарушения), SLO — внутренняя целевая метрика качества сервиса","SLA касается только безопасности","SLO задаётся регулятором"]'::jsonb, 1, 'SLO — цель внутри команды (например, 99,9% успеха запросов), SLA — обязательство перед клиентом с санкциями. Обычно SLO строже SLA, чтобы не нарушить внешнее обязательство.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-req-08', 'requirements', 2, 'Что такое «трассируемость требования»?', '["Возможность отследить, откуда требование пришло (источник), через какие артефакты реализовано и чем проверяется","Логирование обращений к требованию в Confluence","Нумерация требований по порядку","Процесс согласования требования с юристом"]'::jsonb, 0, 'Трассировка связывает бизнес-цель → требование → дизайн/задачи → тесты. Без неё нельзя оценить влияние изменения и доказать, что требование действительно реализовано и проверено.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-int-09', 'integrations', 1, 'Что делает HTTP-статус 429?', '["Сообщает, что ресурс удалён","Too Many Requests: клиент превысил лимит запросов; обычно сопровождается заголовком Retry-After","Ошибка сервера","Указывает на неверный формат тела запроса"]'::jsonb, 1, '429 — стандартный ответ при rate limiting. Корректный клиент должен выдержать паузу из Retry-After, а не ретраить немедленно.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-data-08', 'data', 1, 'Что такое первичный ключ (primary key)?', '["Поле, по которому чаще всего ищут записи","Уникальный идентификатор строки таблицы: не повторяется и не может быть NULL","Поле, связывающее две таблицы","Индекс для ускорения запросов"]'::jsonb, 1, 'PK гарантирует уникальность и существование идентификатора строки. Поле «по которому ищут» — это индекс (он может быть неуникальным), а связывающее поле — внешний ключ.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-arch-08', 'architecture', 2, 'Чем горизонтальное масштабирование отличается от вертикального?', '["Горизонтальное — добавление ресурсов одному серверу, вертикальное — добавление серверов","Горизонтальное — добавление экземпляров сервиса (нужна балансировка и состояние вовне), вертикальное — увеличение мощности одной машины (быстрее упирается в предел)","Это одно и то же","Вертикальное масштабирование применимо только к базам данных"]'::jsonb, 1, 'Горизонтальное масштабирование требует stateless-сервисов (сессии/состояние в Redis/БД), балансировщика и аккуратной работы с блокировками. Вертикальное проще, но ограничено железом и дороже на верхнем пределе.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-mod-06', 'modeling', 2, 'Что на схеме означает cardinality «1..*»?', '["Ровно один","Один или более (минимум один, максимум не ограничен)","Ноль или один","Ноль или более"]'::jsonb, 1, '1..* — минимум один элемент обязателен. 0..* — опционально и много, 0..1 — не более одного. Ошибка в cardinality меняет схему БД (NOT NULL) и поведение интерфейса.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-proc-06', 'process', 1, 'Что такое MVP?', '["Самый важный участник проекта","Минимально жизнеспособный продукт: достаточно функциональности, чтобы проверить гипотезу и получить обратную связь от реальных пользователей","Прототип, который не доходит до пользователей","Полная версия продукта с минимумом багов"]'::jsonb, 1, 'MVP создаётся для обучения и проверки гипотез, а не «чтобы что-то выпустить». Ключевой вопрос аналитика: какую гипотезу проверяем и как измерим результат.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-qual-07', 'quality', 1, 'Что такое smoke-тестирование?', '["Полное регрессионное тестирование","Быстрая проверка основного функционала «работает ли вообще»: критичные сценарии перед углублённым тестированием или после релиза","Тестирование производительности под дымовой нагрузкой","Проверка интерфейса на визуальные дефекты"]'::jsonb, 1, 'Smoke — короткий набор критичных проверок (логин, создание заказа, оплата). Если он не проходит, дальнейшее тестирование бессмысленно.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-int-10', 'integrations', 3, 'Партнёр присылает webhook-и. Какие требования к нашему приёмнику обязательны?', '["Достаточно принимать POST и возвращать 200","Проверка подписи/источника, быстрый 200 с асинхронной обработкой, идемпотентность по идентификатору события, обработка дублей и повторных отправок, журнал и ретрай на своей стороне при пропуске","Синхронная обработка в рамках HTTP-запроса, чтобы партнёр сразу видел результат","Сохранение тела запроса в БД и ручной разбор"]'::jsonb, 1, 'Webhook-и приходят повторно, в неправильном порядке и от подделанного источника. Безопасный приёмник: валидирует подпись, отвечает быстро, обрабатывает в очереди, гасит дубли по eventId, а критичные состояния дополнительно проверяет опросом (pull как страховка от push).', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-data-09', 'data', 3, 'Что такое slowly changing dimension (SCD) типа 2 и зачем он нужен?', '["Медленный запрос к измерению","Хранение истории изменений атрибута измерения в отдельных строках с периодом действия, чтобы факты прошлого считались по тогдашним значениям","Индекс, который обновляется раз в сутки","Способ кэширования справочников"]'::jsonb, 1, 'SCD2 сохраняет историю: у строки есть valid_from/valid_to и флаг актуальности. Без этого при смене сегмента клиента «задним числом» перепишется и история отчётов — классическая ошибка витрин.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
INSERT INTO questions (id, competency, difficulty, question, options, answer, explain, active) VALUES ('q-arch-09', 'architecture', 3, 'Что такое «точка невозврата» в плане миграции?', '["Момент, когда команда устала","Этап, после которого откат становится неоправданно дорогим или невозможным (например, прекращена обратная синхронизация данных); она должна быть явно названа и иметь критерии прохождения","Дата окончания проекта","Момент подписания договора"]'::jsonb, 1, 'План миграции без явной точки невозврата создаёт иллюзию, что вернуться можно всегда. До неё держим обратимые механизмы (двойная запись, обратный CDC), после — только движение вперёд с процедурами исправления данных.', TRUE) ON CONFLICT (id) DO UPDATE SET competency = EXCLUDED.competency, difficulty = EXCLUDED.difficulty, question = EXCLUDED.question, options = EXCLUDED.options, answer = EXCLUDED.answer, explain = EXCLUDED.explain;
