-- Assessment bank: questions with weights (difficulty) and explanations.
-- Source: tasks-mockup/assets/js/questions.js (generated, do not edit by hand).

CREATE TABLE IF NOT EXISTS questions (
  id          TEXT PRIMARY KEY,
  competency  TEXT NOT NULL,
  difficulty  INTEGER NOT NULL DEFAULT 1,
  question    TEXT NOT NULL,
  options     JSONB NOT NULL DEFAULT '[]',
  answer      INTEGER NOT NULL DEFAULT 0,
  explain     TEXT NOT NULL DEFAULT '',
  active      BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS assessment_submissions (
  id            UUID PRIMARY KEY,
  user_id       UUID NOT NULL REFERENCES users (id) ON DELETE CASCADE,
  answers       JSONB NOT NULL DEFAULT '{}',
  duration_sec  INTEGER NOT NULL DEFAULT 0,
  score         NUMERIC NOT NULL DEFAULT 0,
  score_rounded INTEGER NOT NULL DEFAULT 0,
  grade_id      TEXT NOT NULL DEFAULT '',
  result        JSONB NOT NULL DEFAULT '{}',
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS ix_assessment_user ON assessment_submissions (user_id, created_at DESC);

